Definition mtx_unlock_post (ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (M lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a2 a3 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (M, M + 40)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ APMutex m' M 0
    /\ a0 = wz 0.

Definition mtx_unlock_stmt : Prop :=
  forall (M lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  APMutex m M EBUSY ->
  stk bsegs m lo (bv_unsigned sp) -> lo + MTX_UNLOCK_STACK <= bv_unsigned sp -> aceil <= lo ->
  (M + 40 <= lo \/ bv_unsigned sp <= M) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  evt bsegs (mtx_unlock_post ra sp gp tp s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc M lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz M) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_MTX_UNLOCK) fc None m (seg_rom bsegs)).

